-- bc-telemetry storage layout's functions, for PostgreSQL.
--
-- Generated by bc-telemetry-gen. Do not edit.
-- Apply it after layout.sql, and again whenever it changes: every function is CREATE OR REPLACE,
-- in one transaction, so it applies over itself and over the functions an earlier file left, and
-- lands whole or not at all. A body is code, so changing one is not a new layout version; a
-- changed signature is, since CREATE OR REPLACE cannot make one.

BEGIN;

-- ---------------------------------------------------------------------------------------------
-- Maintenance. Whoever schedules it passes the instant; it reads no clock of its own.
-- ---------------------------------------------------------------------------------------------

-- Keeps the partitions for `days_kept` days back through `days_ahead` days forward of
-- `at_instant`'s UTC day, drops the partitions of every earlier day, and forgets the erasures
-- that only those days could have matched. Call it with the horizons named —
-- `telemetry.maintain(now(), days_ahead => 2, days_kept => 30)` — since both are integers and a
-- swapped pair is a window of the wrong length rather than an error.
--
-- A partition's bounds are written as text and read back by the statement that creates it, so
-- the function fixes the date style and time zone that text is spelled in rather than taking the
-- calling session's.
--
-- Creating and dropping a partition locks its table exclusively, and an exclusive request that
-- waits is waited behind by every ingest that comes after it: a maintenance run stuck behind one
-- long transaction would stall every writer. So it waits at most five seconds for a lock and then
-- fails, to be run again — its partitions are made days ahead, so a missed run costs nothing yet.
CREATE OR REPLACE FUNCTION telemetry.maintain(
    at_instant timestamptz, days_ahead integer, days_kept integer)
    RETURNS TABLE (days_created integer, days_dropped integer, erasures_pruned bigint)
    LANGUAGE plpgsql
    SET DateStyle = 'ISO, YMD'
    SET TimeZone = 'UTC'
    SET lock_timeout = '5s'
    AS $$
DECLARE
    today constant date := (at_instant AT TIME ZONE 'UTC')::date;
    first_kept constant date := today - days_kept;
    last_ahead constant date := today + days_ahead;
    this_day date;
    this_table text;
BEGIN
    IF days_ahead < 0 OR days_kept < 0 THEN
        RAISE EXCEPTION
            'telemetry.maintain: days_ahead (%) and days_kept (%) must not be negative',
            days_ahead, days_kept;
    END IF;

    -- One maintenance run at a time; an ingest reading the days is not held up.
    LOCK TABLE telemetry.live_days IN SHARE ROW EXCLUSIVE MODE;

    days_dropped := 0;
    FOR this_day IN
        SELECT live.day FROM telemetry.live_days AS live WHERE live.day < first_kept ORDER BY live.day
    LOOP
        FOREACH this_table IN ARRAY ARRAY['spans', 'metrics', 'logs'] LOOP
            EXECUTE format(
                'DROP TABLE telemetry.%I', this_table || '_' || to_char(this_day, 'YYYYMMDD'));
        END LOOP;
        DELETE FROM telemetry.live_days AS live WHERE live.day = this_day;
        days_dropped := days_dropped + 1;
    END LOOP;

    days_created := 0;
    FOR this_day IN
        SELECT wanted::date
        FROM generate_series(first_kept::timestamp, last_ahead::timestamp, interval '1 day') AS wanted
        WHERE NOT EXISTS (SELECT 1 FROM telemetry.live_days AS live WHERE live.day = wanted::date)
        ORDER BY wanted
    LOOP
        FOREACH this_table IN ARRAY ARRAY['spans', 'metrics', 'logs'] LOOP
            EXECUTE format(
                'CREATE TABLE telemetry.%I PARTITION OF telemetry.%I FOR VALUES FROM (%L) TO (%L)',
                this_table || '_' || to_char(this_day, 'YYYYMMDD'),
                this_table,
                this_day::timestamp AT TIME ZONE 'UTC',
                (this_day + 1)::timestamp AT TIME ZONE 'UTC');
        END LOOP;
        INSERT INTO telemetry.live_days (day) VALUES (this_day);
        days_created := days_created + 1;
    END LOOP;

    WITH pruned AS (
        DELETE FROM telemetry.erasures AS erasure
        WHERE erasure.erased_at < first_kept::timestamp AT TIME ZONE 'UTC'
        RETURNING 1
    )
    SELECT count(*) INTO erasures_pruned FROM pruned;

    RETURN NEXT;
END;
$$;

-- ---------------------------------------------------------------------------------------------
-- Erasure and ingest, held off each other.
--
-- An ingest and an erasure of the same customer each read what the other writes: the ingest
-- refuses a record whose customer is erased, and the erasure deletes what is stored. Under READ
-- COMMITTED a statement sees only what had committed when it began, so without more an ingest
-- that begins while an erasure is uncommitted stores the record, and an erasure that begins while
-- an ingest is uncommitted misses it. So they take one advisory lock, keyed by the erasures
-- table's own OID: every ingest takes it shared, so ingests never wait on each other, and an
-- erasure takes it exclusive, so each waits for the other to commit — and the statements after
-- the wait see what it committed. An advisory lock needs no privilege on any table, so a writer
-- granted only the ingest step can take it.
-- ---------------------------------------------------------------------------------------------

-- Deletes every record about `customers` of `for_organization`, and records the erasure so the
-- ingest step refuses the ones still on their way. Run it inside the transaction that erases the
-- customer's other data, and that transaction READ COMMITTED: a REPEATABLE READ or SERIALIZABLE
-- transaction reads from a snapshot it may have taken before the lock, which would miss what an
-- ingest committed in between — so either is refused rather than half-erased.
CREATE OR REPLACE FUNCTION telemetry.erase_customers(
    for_organization text, customers text[], erased_at timestamptz)
    RETURNS TABLE (spans_deleted bigint, metrics_deleted bigint, logs_deleted bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF current_setting('transaction_isolation') <> 'read committed' THEN
        RAISE EXCEPTION
            'telemetry.erase_customers: run it in a READ COMMITTED transaction, not %',
            upper(current_setting('transaction_isolation'));
    END IF;
    PERFORM pg_advisory_xact_lock('telemetry.erasures'::regclass::oid::bigint);

    INSERT INTO telemetry.erasures AS erasure (organization, customer, erased_at)
    SELECT for_organization, subject, erase_customers.erased_at
    FROM unnest(customers) AS subject
    ON CONFLICT ((COALESCE(organization, '')), customer)
        DO UPDATE SET erased_at = GREATEST(erasure.erased_at, EXCLUDED.erased_at);

    WITH deleted AS (
        DELETE FROM telemetry.spans AS record
        WHERE record.customer = ANY (customers)
          AND record.organization IS NOT DISTINCT FROM for_organization
        RETURNING 1
    )
    SELECT count(*) INTO spans_deleted FROM deleted;

    WITH deleted AS (
        DELETE FROM telemetry.metrics AS record
        WHERE record.customer = ANY (customers)
          AND record.organization IS NOT DISTINCT FROM for_organization
        RETURNING 1
    )
    SELECT count(*) INTO metrics_deleted FROM deleted;

    WITH deleted AS (
        DELETE FROM telemetry.logs AS record
        WHERE record.customer = ANY (customers)
          AND record.organization IS NOT DISTINCT FROM for_organization
        RETURNING 1
    )
    SELECT count(*) INTO logs_deleted FROM deleted;

    RETURN NEXT;
END;
$$;

-- ---------------------------------------------------------------------------------------------
-- Ingest: the one step every write goes through. A writer, per batch:
--
--   SELECT telemetry.open_staging();
--   COPY pg_temp.bc_telemetry_staged_spans (...) FROM STDIN;
--   SELECT * FROM telemetry.ingest_spans();
--
-- and likewise for metrics and logs. The staging tables are the session's own.
-- ---------------------------------------------------------------------------------------------

-- Creates this session's staging tables if it has none, and empties them: what an earlier batch
-- left staged after a failure is not this batch's. A staging table takes its table's shape when it is
-- made, so a session that outlives a migration would keep the old one, and an ingest reading a column
-- the migration added would fail every batch until the writer reconnected. The session therefore
-- records the layout version its staging tables were made at, and remakes them when
-- `layout_version()` answers another.
CREATE OR REPLACE FUNCTION telemetry.open_staging() RETURNS void
    LANGUAGE plpgsql
    SET client_min_messages = warning
    AS $$
BEGIN
    IF current_setting('bc_telemetry.staged_layout', true) IS DISTINCT FROM
            telemetry.layout_version()::text THEN
        DROP TABLE IF EXISTS pg_temp.bc_telemetry_staged_spans,
                             pg_temp.bc_telemetry_staged_metrics,
                             pg_temp.bc_telemetry_staged_logs;
        PERFORM set_config('bc_telemetry.staged_layout', telemetry.layout_version()::text, false);
    END IF;
    CREATE TEMPORARY TABLE IF NOT EXISTS bc_telemetry_staged_spans
        (LIKE telemetry.spans) ON COMMIT PRESERVE ROWS;
    CREATE TEMPORARY TABLE IF NOT EXISTS bc_telemetry_staged_metrics
        (LIKE telemetry.metrics) ON COMMIT PRESERVE ROWS;
    CREATE TEMPORARY TABLE IF NOT EXISTS bc_telemetry_staged_logs
        (LIKE telemetry.logs) ON COMMIT PRESERVE ROWS;
    TRUNCATE pg_temp.bc_telemetry_staged_spans,
             pg_temp.bc_telemetry_staged_metrics,
             pg_temp.bc_telemetry_staged_logs;
END;
$$;

-- Each ingest function takes the erasure lock shared (above), then moves every staged row of its
-- kind into the table in one statement and returns four counts:
--   inserted      rows stored
--   out_of_range  rows whose UTC day has no partition                        (dropped)
--   erased        rows about a customer erased at or after the row's time    (dropped)
--   duplicate     rows whose key is already stored: a retried batch          (not dropped)

CREATE OR REPLACE FUNCTION telemetry.ingest_spans(
    OUT inserted bigint, OUT out_of_range bigint, OUT erased bigint, OUT duplicate bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock_shared('telemetry.erasures'::regclass::oid::bigint);
    WITH staged AS (
        DELETE FROM pg_temp.bc_telemetry_staged_spans RETURNING *
    ), judged AS (
        SELECT staged.*,
               EXISTS (
                   SELECT 1 FROM telemetry.live_days AS live
                   WHERE live.day = (staged.time AT TIME ZONE 'UTC')::date
               ) AS is_live,
               staged.customer IS NOT NULL AND EXISTS (
                   SELECT 1 FROM telemetry.erasures AS erasure
                   WHERE COALESCE(erasure.organization, '') = COALESCE(staged.organization, '')
                     AND erasure.customer = staged.customer
                     AND staged.time <= erasure.erased_at
               ) AS is_erased
        FROM staged
    ), written AS (
        INSERT INTO telemetry.spans (
            time, record_id, module, name, schema_version, service_name, organization, customer,
            trace_id, span_id, attributes, end_time, parent_span_id, kind, status,
            status_message, events)
        SELECT time, record_id, module, name, schema_version, service_name, organization, customer,
               trace_id, span_id, attributes, end_time, parent_span_id, kind, status,
               status_message, events
        FROM judged
        WHERE is_live AND NOT is_erased
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT (SELECT count(*) FROM written),
           count(*) FILTER (WHERE NOT is_live),
           count(*) FILTER (WHERE is_live AND is_erased),
           count(*) FILTER (WHERE is_live AND NOT is_erased) - (SELECT count(*) FROM written)
    INTO inserted, out_of_range, erased, duplicate
    FROM judged;
END;
$$;

CREATE OR REPLACE FUNCTION telemetry.ingest_metrics(
    OUT inserted bigint, OUT out_of_range bigint, OUT erased bigint, OUT duplicate bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock_shared('telemetry.erasures'::regclass::oid::bigint);
    WITH staged AS (
        DELETE FROM pg_temp.bc_telemetry_staged_metrics RETURNING *
    ), judged AS (
        SELECT staged.*,
               EXISTS (
                   SELECT 1 FROM telemetry.live_days AS live
                   WHERE live.day = (staged.time AT TIME ZONE 'UTC')::date
               ) AS is_live,
               staged.customer IS NOT NULL AND EXISTS (
                   SELECT 1 FROM telemetry.erasures AS erasure
                   WHERE COALESCE(erasure.organization, '') = COALESCE(staged.organization, '')
                     AND erasure.customer = staged.customer
                     AND staged.time <= erasure.erased_at
               ) AS is_erased
        FROM staged
    ), written AS (
        INSERT INTO telemetry.metrics (
            time, record_id, module, name, schema_version, service_name, organization, customer,
            trace_id, span_id, attributes, kind, value)
        SELECT time, record_id, module, name, schema_version, service_name, organization, customer,
               trace_id, span_id, attributes, kind, value
        FROM judged
        WHERE is_live AND NOT is_erased
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT (SELECT count(*) FROM written),
           count(*) FILTER (WHERE NOT is_live),
           count(*) FILTER (WHERE is_live AND is_erased),
           count(*) FILTER (WHERE is_live AND NOT is_erased) - (SELECT count(*) FROM written)
    INTO inserted, out_of_range, erased, duplicate
    FROM judged;
END;
$$;

CREATE OR REPLACE FUNCTION telemetry.ingest_logs(
    OUT inserted bigint, OUT out_of_range bigint, OUT erased bigint, OUT duplicate bigint)
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_advisory_xact_lock_shared('telemetry.erasures'::regclass::oid::bigint);
    WITH staged AS (
        DELETE FROM pg_temp.bc_telemetry_staged_logs RETURNING *
    ), judged AS (
        SELECT staged.*,
               EXISTS (
                   SELECT 1 FROM telemetry.live_days AS live
                   WHERE live.day = (staged.time AT TIME ZONE 'UTC')::date
               ) AS is_live,
               staged.customer IS NOT NULL AND EXISTS (
                   SELECT 1 FROM telemetry.erasures AS erasure
                   WHERE COALESCE(erasure.organization, '') = COALESCE(staged.organization, '')
                     AND erasure.customer = staged.customer
                     AND staged.time <= erasure.erased_at
               ) AS is_erased
        FROM staged
    ), written AS (
        INSERT INTO telemetry.logs (
            time, record_id, module, name, schema_version, service_name, organization, customer,
            trace_id, span_id, attributes, severity, body)
        SELECT time, record_id, module, name, schema_version, service_name, organization, customer,
               trace_id, span_id, attributes, severity, body
        FROM judged
        WHERE is_live AND NOT is_erased
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT (SELECT count(*) FROM written),
           count(*) FILTER (WHERE NOT is_live),
           count(*) FILTER (WHERE is_live AND is_erased),
           count(*) FILTER (WHERE is_live AND NOT is_erased) - (SELECT count(*) FROM written)
    INTO inserted, out_of_range, erased, duplicate
    FROM judged;
END;
$$;

COMMIT;
